import { Point } from '@influxdata/influxdb-client';
import { Logger } from '@nestjs/common';
import { ApiProperty } from '@nestjs/swagger';

import { InfluxService } from '../../influx/influx.service.js';

import {
    countBasedUnits,
    dataBasedUnits,
    overageAllowedEnum,
    roundingEnum,
    timeBasedUnits,
    infrastructureType,
    SampleType,
    aggregationInterval,
    aggregationMethod,
} from '../dto/create-dimension.dto.js';

export enum dimensionUnit {
    Minute = 'Minutes',
    Hour = 'Hours',
    Gb = 'Gbs',
    Mb = 'Mbs',
    Count = 'Count',
}

export enum numericalType {
    float = 'float',
    int = 'int',
}

class PriceSegments {
    /**
     * A unit price to be associated in the tier
     * For instance a lower tier may have 0.05$ per Gb where as a higher tier may be 0.03$ per Gb
     *
     */
    public price?: string;
    /**
     * The lower limit of this tier in terms of usage
     *
     */
    public lowerLimit?: string;
    /**
     * The upper limit for this tier in terms of usage
     *
     */
    public upperLimit?: string;
}
/**
 * @author Daniel Wasserlauf <daniel.wasserlauf@paigo.tech>
 *
 * @Class
 * The Catagorical subclass contains information for a catagorical element inside a dimension
 * It is not completed nor used at the moment
 *
 * @TODO  complete this class
 * */
export class Categorical {
    values?: {
        SLA?: string;
    };
    public static transformer(catagorical: Categorical, point: Point) {
        return point;
    }

    public static dbModelToEntity(row) {
        return {};
    }
}

export enum aggregationType {
    aggregation = 'aggregation',
}

/**
 * @author Daniel Wasserlauf <daniel.wasserlauf@paigo.tech>
 *
 * @Class
 * The Numerical class is treated as a supporting structure to the dimension entity.
 * Specifically it contains the information needed to create a numerical based dimension.
 * As opposed to a catagorical dimension
 * */
export class Numerical {
    /**
     * The numericalType is used when aggregating and calculating data
     * For percision purposes when calculating the data its important to know ahead of time if the type is an interger or a float
     * @example "float"
     * @example "int"
     */
    public numericalType: numericalType;

    public dimensionUnit: timeBasedUnits | countBasedUnits | dataBasedUnits;

    public dimensionUnitType: 'count' | 'time' | 'data';

    /**
     * How often usage should be aggregated to, this is a window where usage will be aggregated up till.
     * For example if Paigo measures ever 10 minutes for uptime, 6 measurements would be taken, if aggregation is set to hourly, the usage will be totaled up and set for the hour.
     * @example Hour
     * @example Day
     * @example Month
     */
    public aggregationInterval: aggregationInterval;

    /**
     * The Aggregation Method associated with a dimension, typically will be total, however other options are supported
     * @example "sum"
     *
     */
    public aggregationMethod: aggregationMethod;

    /**
     * The Price Tier object is optional,
     * it provides additional information about any tier limits which the dimension should be aware of
     *
     */
    public priceSegments?: PriceSegments[];
    /**
     *
     * The sample type used for the data. Counter is a monotonically increasing value. Gauge is a value that can go up or down.
     * @example "counter"
     * @example "gauge"
     */
    public sampleType: SampleType;

    public usageIncrement: number;

    public rounding: roundingEnum;

    public usageEntitlement?: number | 'inf';

    public overageAllowed?: overageAllowedEnum;

    constructor(numericalEntityInfo: Numerical) {
        if (numericalEntityInfo) {
            const {
                numericalType,
                dimensionUnit,
                aggregationInterval,
                aggregationMethod,
                priceSegments,
                sampleType,
                usageIncrement,
                rounding,
                usageEntitlement,
                overageAllowed,
                dimensionUnitType,
            } = numericalEntityInfo;
            this.numericalType = numericalType;
            this.dimensionUnit = dimensionUnit;
            this.sampleType = sampleType;
            this.aggregationInterval = aggregationInterval;
            this.aggregationMethod = aggregationMethod;
            this.priceSegments = priceSegments;
            this.usageIncrement = usageIncrement;
            this.rounding = rounding;
            this.usageEntitlement = usageEntitlement;
            this.overageAllowed = overageAllowed ? overageAllowed : overageAllowedEnum.false;
            this.dimensionUnitType = dimensionUnitType;
        }
    }

    public static transformer = (
        {
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments,
            sampleType,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            dimensionUnitType,
        }: Numerical,
        point: Point,
    ): Point => {
        point.tag('numericalType', numericalType);
        point.tag('dimensionUnit', dimensionUnit);
        point.tag('aggregationInterval', aggregationInterval);
        point.tag('aggregationMethod', aggregationMethod);
        point.tag('sampleType', sampleType);
        point.tag('priceSegments', JSON.stringify(priceSegments));
        if (usageIncrement !== undefined) {
            point.tag('usageIncrement', usageIncrement.toString());
        }

        point.tag('rounding', rounding);
        if (usageEntitlement !== undefined && usageEntitlement !== null) {
            point.tag('usageEntitlement', usageEntitlement.toString());
        }

        if (overageAllowed !== undefined && overageAllowed !== null) {
            point.tag('overageAllowed', overageAllowed);
        }

        point.tag('dimensionUnitType', dimensionUnitType);
        return point;
    };
    public static dbModelToEntity = (row: any): Numerical => {
        const {
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments,
            sampleType,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            dimensionUnitType,
        } = row;
        return new Numerical({
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments: JSON.parse(priceSegments),
            sampleType,
            usageIncrement: parseInt(usageIncrement),
            rounding,
            usageEntitlement: usageEntitlement ? parseInt(usageEntitlement) : undefined,
            overageAllowed,
            dimensionUnitType,
        });
    };
}

/**
 * @author Daniel Wasserlauf <daniel.wasserlauf@paigo.tech>
 *
 * @Class
 * The Dimension Entity represents the backend data format for the Dimensions.
 * Contained within are two important static methods.
 *
 * @function transformer
 *
 *  The transformation from the entity to the influx point array for writing to the DB.
 *
 * @function dbModelToEntity
 *
 * The transformation from the DB model to an entity. Specifically must only give a single row from the ledger
 *
 * These functions exist on almost all entities and deal with changing the entity to a compatible InfluxDB format and back.
 * These are useful during the reads and writes to and from the ledger in InfluxDB
 */
export class DimensionEntity {
    private static readonly logger = new Logger(DimensionEntity.name);
    public static _measurement = 'DimensionConfig';

    public dimensionId: string;

    public businessID: string;
    public typeofDimension: string;
    public dimensionName: string;
    public measurementId: string;
    public infrastructureType: infrastructureType;
    public numerical: Numerical;
    public categorical: Categorical;
    public metadata?: Record<string, string | number | null>;

    constructor(entityInfo: DimensionEntity) {
        if (entityInfo) {
            const {
                typeofDimension,
                categorical,
                numerical,
                businessID,
                dimensionId,
                infrastructureType,
                dimensionName,
                measurementId,
                metadata,
            } = entityInfo;

            this.dimensionId = dimensionId;
            this.businessID = businessID;
            this.infrastructureType = infrastructureType;
            this.typeofDimension = typeofDimension;
            this.dimensionName = dimensionName;
            this.measurementId = measurementId;
            if (typeofDimension === 'numerical') {
                this.numerical = numerical;
            }
            if (typeofDimension === 'categorical') {
                this.categorical = categorical;
            }
            this.metadata = metadata;
        }
    }
    static transformer = (
        {
            dimensionId,
            businessID,
            typeofDimension,
            categorical,
            numerical,
            dimensionName,
            infrastructureType,
            measurementId,
            metadata,
        }: DimensionEntity,
        influxService: InfluxService,
    ): Point => {
        const dimensionEntityPoint = influxService.getPoint(DimensionEntity._measurement);

        dimensionEntityPoint.tag('dimensionId', dimensionId);
        dimensionEntityPoint.tag('businessID', businessID);
        dimensionEntityPoint.tag('measurementId', measurementId);
        dimensionEntityPoint.tag('infrastructureType', infrastructureType);
        dimensionEntityPoint.tag('typeofDimension', typeofDimension);

        if (typeofDimension === 'numerical') {
            Numerical.transformer(numerical, dimensionEntityPoint);
        }

        if (typeofDimension === 'catagorical') {
            Categorical.transformer(categorical, dimensionEntityPoint);
        }
        if (metadata) {
            dimensionEntityPoint.tag('metadata', JSON.stringify(metadata));
        }
        dimensionEntityPoint.stringField('dimensionName', dimensionName);

        return dimensionEntityPoint;
    };

    static dbModelToEntity(dbModel): DimensionEntity {
        const { _value, ...rest } = dbModel;

        const {
            infrastructureType,
            businessID,
            dimensionId,
            typeofDimension,
            measurementId,
            metadata: influxMetadata,
        } = rest;
        let numerical;
        let categorical;
        if (typeofDimension === 'numerical') {
            numerical = Numerical.dbModelToEntity(rest);
        }
        if (typeofDimension === 'categorical') {
            categorical = Categorical.dbModelToEntity(rest);
        }
        const input = {
            typeofDimension,
            infrastructureType,
            businessID,
            dimensionId,
            numerical,
            categorical,
            dimensionName: _value,
            measurementId,
            metadata: influxMetadata ? JSON.parse(influxMetadata) : undefined,
        };

        return new DimensionEntity(input);
    }
}

import {
    BadRequestException,
    ConflictException,
    forwardRef,
    Inject,
    Injectable,
    Logger,
    NotFoundException,
} from '@nestjs/common';
import { InfluxService } from '../influx/influx.service.js';
import {
    CreateDimensionDto,
    CreateDimensionResponse,
    SampleType,
    aggregationInterval,
    aggregationMethod,
    infrastructureType,
    UpdateDimensionResponse,
    overageAllowedEnum,
} from './dto/create-dimension.dto.js';
import { DeleteDimensionDto, DeleteDimensionResponseDto } from './dto/deleteDimension.dto.js';
import { ReadDimensionDto, ReadDimensionResponse, ReadDimensionResponseData } from './dto/read-dimension.dto.js';
import { v4 } from 'uuid';
import { aggregationType, DimensionEntity, numericalType } from './entities/dimensions.entity.js';
import { BasicResponseDTO } from '../basicResponseDTO.js';
import { UpdateDimensionDto } from './dto/update-dimension.dto.js';
import { MeasurementConfigService } from '../measurement-config/measurement-config.service.js';
import { OfferingService } from '../offering/offering.service.js';
import { SchedulerService } from '../scheduler/scheduler.service.js';
import {
    AgentAccessInformation,
    InfrastructureAccessInformation,
    SupportedResources,
} from '../measurement-config/entities/measurement-config.entity.js';
import { schedulerType, SchedulerStatus, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto.js';
import { AggregationDto } from './dto/aggregation.dto.js';
import { AuditService } from '../audit/audit.service.js';
import { AuditScope } from '../audit/entities/audit.interface.js';
import { measurementMode } from '../measurement-config/dto/create-measurement-config.dto.js';
import { joinMetadataObjectsAndRemoveNulls } from '../utils/shared/utils.js';

@Injectable()
export class DimensionsService {
    private static readonly logger = new Logger(DimensionsService.name);
    constructor(
        @Inject(forwardRef(() => InfluxService)) readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => MeasurementConfigService)) readonly measurementConfigService: MeasurementConfigService,
        @Inject(forwardRef(() => OfferingService)) readonly offeringService: OfferingService,
        @Inject(forwardRef(() => SchedulerService)) readonly schedulerService: SchedulerService,
    ) {}
    async create(createDimensionDto: CreateDimensionDto, subject): Promise<CreateDimensionResponse> {
        const dimensionId = v4();
        // create the Points and commit it
        const { loadPoints } = this.InfluxService;
        const { measurementId, businessID } = createDimensionDto;
        let inputForEntity;
        if (measurementId) {
            inputForEntity = await this.measurementConfigService.createMeasurementConfig(
                createDimensionDto,
                measurementId,
                createDimensionDto.businessID,
                dimensionId,
            );
        } else {
            inputForEntity = this.transformDtoToEntityInput(createDimensionDto, dimensionId);
        }
        DimensionsService.logger.debug(`Input for Entity`, JSON.stringify(inputForEntity));
        const dimensionModel = new DimensionEntity(inputForEntity);
        const dbModel = DimensionEntity.transformer(dimensionModel, this.InfluxService);

        await loadPoints(`${process.env.STAGE}-config`, process.env.INFLUX_ORG, [dbModel]);

        if (measurementId) {
            const {
                data: [{ measurementMode: argumentMeasurementMode, measurementConfiguration }],
            } = await this.measurementConfigService.findOne({ measurementId, businessID });
            if (argumentMeasurementMode === measurementMode.infrastructureBased) {
                const accessInformation = measurementConfiguration as InfrastructureAccessInformation;
                await this.schedulerService.create({
                    schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                        dimensionId,
                        resourceType: accessInformation.resourceType,
                    }),
                    schedulerType: schedulerType.dimensionDataGathering,
                    schedulerStatus: SchedulerStatus.live,
                    scheduleParameters: {
                        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                        //@ts-ignore
                        dimensionType: this.ressourceTypeToDimensionType(accessInformation.resourceType),
                        dimensionId,
                        businessID,
                        rate: SupportedMeasurementFrequencies.everyFiveMinutes,
                        iamRoleArn: accessInformation?.iamRoleArn,
                        externalId: accessInformation?.externalId,
                        region: accessInformation?.region,
                    },
                    rate: SupportedMeasurementFrequencies.everyFiveMinutes,
                    subject,
                    businessID,
                });
            } else if (argumentMeasurementMode === measurementMode.agentBased) {
                const accessInformation = measurementConfiguration as AgentAccessInformation;
                await this.schedulerService.create({
                    schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                        dimensionId,
                        resourceType: accessInformation.hostingPlatform,
                    }),
                    schedulerType: schedulerType.dimensionDataGathering,
                    schedulerStatus: SchedulerStatus.live,
                    scheduleParameters: {
                        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                        //@ts-ignore
                        dimensionType: this.ressourceTypeToDimensionType(infrastructureType.podCPUHours),
                        dimensionId,
                        businessID,
                        rate: SupportedMeasurementFrequencies.everyHour,
                        iamRoleArn: accessInformation?.iamRoleArn,
                        externalId: accessInformation?.externalId,
                    },
                    rate: SupportedMeasurementFrequencies.everyHour,
                    subject,
                    businessID,
                });
                await this.schedulerService.create({
                    schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                        dimensionId,
                        resourceType: `${accessInformation.hostingPlatform}-${infrastructureType.reservedInstanceHours}`,
                    }),
                    schedulerType: schedulerType.dimensionDataGathering,
                    schedulerStatus: SchedulerStatus.live,
                    scheduleParameters: {
                        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                        //@ts-ignore
                        dimensionType: infrastructureType.reservedInstanceHours,
                        iamRoleArn: accessInformation?.iamRoleArn,
                        externalId: accessInformation?.externalId,
                    },
                    rate: SupportedMeasurementFrequencies.everyHour,
                    subject,
                    businessID,
                });
            }
        }

        return { message: 'created dimension document', dimensionId };
    }
    private createKeyForManagedInfraDimensionSchedule({ dimensionId, resourceType }) {
        return `${dimensionId}-${resourceType}`;
    }
    private ressourceTypeToDimensionType(ressourceType: SupportedResources): infrastructureType {
        if (ressourceType === SupportedResources.ebssnapshot) {
            return infrastructureType.ebsSnapshot;
        }
        if (ressourceType === SupportedResources.ebs) {
            return infrastructureType.ebsVolumeProvisionedCapacity;
        }
        if (ressourceType === SupportedResources.k8sPod) {
            return infrastructureType.podCPUHours;
        }
        if (ressourceType === SupportedResources.ec2) {
            return infrastructureType.instanceRunningTime;
        }
        if (ressourceType === SupportedResources.ec2Egress) {
            return infrastructureType.ec2Egress;
        }
    }

    async findAll({ businessID }): Promise<ReadDimensionResponse> {
        const dimensionIds = await this.InfluxService.getAllDimensionIds({ businessID });
        const errors = [];
        const results = await Promise.all(
            dimensionIds.map(async ({ dimensionId }) => {
                try {
                    const {
                        data: [readDimensionData],
                    } = await this.findOne({ businessID, dimensionId });
                    return readDimensionData;
                } catch (error) {
                    if (error.status === 404) {
                        // If a subset of documents are missing then catch the error and continue
                        // This realistically should never happen, since we are gathering all the ids from the same DB, but you never know
                        errors.push(error.message);
                    } else {
                        throw error;
                    }
                }
            }),
        );
        if (errors.length) {
            DimensionsService.logger.log(`Errors occured in find all dimensions, likely some Ids were disconnected`);
            DimensionsService.logger.error(errors);
        }
        const filtered = results.filter((r) => r);
        if (results.length && results.length > 0) {
            return { data: filtered, message: 'Found Dimensions' };
        } else {
            return { data: [], message: 'No Dimensions found' };
        }
    }

    async findOne({
        businessID,
        dimensionId,
    }: ReadDimensionDto): Promise<{ data: ReadDimensionResponseData[]; message: string }> {
        const { getSingleDimension } = this.InfluxService;
        const dbModel = await getSingleDimension({ businessID, dimensionId });
        if (dbModel.length) {
            const entity = DimensionEntity.dbModelToEntity(dbModel[0]);
            let measurementData;
            if (entity?.measurementId) {
                try {
                    const {
                        data: [measurementInfo],
                    } = await this.measurementConfigService.findOne({
                        measurementId: entity.measurementId,
                        businessID,
                    });
                    measurementData = measurementInfo;
                } catch (error) {
                    if (error instanceof NotFoundException) {
                        AuditService.publishEvent({
                            message: 'Measurement not found for dimension',
                            data: [{ dimensionId, measurementId: entity.measurementId }],
                            topic: AuditScope.ERROR,
                        });
                    } else {
                        throw error;
                    }
                }
            }
            const { measurementId, ...rest } = new CreateDimensionDto(entity);

            return {
                data: [
                    {
                        dimensionId: entity.dimensionId,
                        ...rest,
                        ...(measurementData && { measurement: { ...measurementData } }),
                    },
                ],
                message: 'Found Dimension',
            };
        } else {
            throw new NotFoundException(`No Dimensions found with ID:${dimensionId}`);
        }
    }

    async remove(deleteDimensionDto: DeleteDimensionDto): Promise<DeleteDimensionResponseDto> {
        const { dimensionId, businessID } = deleteDimensionDto;
        const {
            data: [{ measurement }],
        } = await this.findOne({ dimensionId, businessID });
        try {
            const { data: offeringIds } = await this.offeringService.findOfferingIdsByDimensionId({
                dimensionId,
                businessID,
            });
            if (offeringIds.length) {
                throw new ConflictException(
                    `Cannot Delete Dimensions when they are attached to Offerings, remove dimensions from offerings before deleting. Current OfferingIds using the dimension: ${offeringIds.reduce(
                        (acc, item) => {
                            acc += `${item}   `;
                            return acc;
                        },
                        '',
                    )} `,
                );
            }
        } catch (error) {
            if (error instanceof NotFoundException) {
                // Ignore
            } else {
                throw error;
            }
        }

        if (measurement) {
            try {
                if (measurement.measurementMode === measurementMode.infrastructureBased) {
                    const accessInformation = measurement?.measurementConfiguration as InfrastructureAccessInformation;
                    await this.schedulerService.remove({
                        schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                            dimensionId,
                            resourceType: accessInformation.resourceType,
                        }),
                        businessID,
                    });
                }
            } catch (e) {
                AuditService.publishEvent({
                    data: [e],
                    message: 'Error removing measurement dimension from scheduler',
                    topic: AuditScope.ERROR,
                });
            }
        }

        await this.InfluxService.dropDimensionConfig(
            `${process.env.STAGE}-config`,
            process.env.INFLUX_ORG,
            businessID,
            dimensionId,
        );
        return { message: 'deleted dimension document' };
    }
    async update(
        { dimensionId, businessID, ...updatedFields }: UpdateDimensionDto,
        subject: string,
    ): Promise<UpdateDimensionResponse> {
        const {
            data: [{ ...rest }],
        } = await this.findOne({ dimensionId, businessID });
        if (updatedFields?.usageEntitlement === null || updatedFields?.overageAllowed === null) {
            if (
                updatedFields?.usageEntitlement === null &&
                rest?.overageAllowed !== overageAllowedEnum.false &&
                updatedFields?.overageAllowed !== null &&
                updatedFields?.overageAllowed !== overageAllowedEnum.false
            ) {
                throw new BadRequestException(`If entitlement is removed then overage must be removed as well`);
            }
        }
        const { loadPoints } = this.InfluxService;
        const input = this.transformDtoToEntityInput(
            {
                ...rest,
                ...updatedFields,
                businessID,
                metadata: joinMetadataObjectsAndRemoveNulls(rest?.metadata, updatedFields?.metadata),
            },
            dimensionId,
        );
        const entity = new DimensionEntity(input);
        const dimensionDBModel = DimensionEntity.transformer(entity, this.InfluxService);

        if (updatedFields.measurementId) {
            // Check to see if measurement exists
            const {
                data: [measurement],
            } = await this.measurementConfigService.findOne({
                measurementId: updatedFields.measurementId,
                businessID,
            });
            if (measurement.measurementMode === measurementMode.infrastructureBased) {
                const accessInformation = measurement?.measurementConfiguration as InfrastructureAccessInformation;
                try {
                    DimensionsService.logger.log('Creating new schedules for data gathering for the Dimension');
                    await this.schedulerService.remove({
                        schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                            dimensionId,
                            resourceType: accessInformation.resourceType,
                        }),
                        businessID,
                    });
                } catch (e) {
                    AuditService.publishEvent({
                        data: [e],
                        message: `Error removing dimension from scheduler: dimensionId: ${dimensionId}`,
                        topic: AuditScope.ERROR,
                    });
                }
                try {
                    await this.schedulerService.create({
                        schedulerID: this.createKeyForManagedInfraDimensionSchedule({
                            dimensionId,
                            resourceType: accessInformation.resourceType,
                        }),
                        schedulerType: schedulerType.dimensionDataGathering,
                        schedulerStatus: SchedulerStatus.live,
                        scheduleParameters: {
                            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                            //@ts-ignore
                            dimensionType: this.ressourceTypeToDimensionType(accessInformation.resourceType),
                            dimensionId,
                            businessID,
                            rate: SupportedMeasurementFrequencies.everyFiveMinutes,
                            iamRoleArn: accessInformation?.iamRoleArn,
                            externalId: accessInformation?.externalId,
                            region: accessInformation?.region,
                        },
                        rate: SupportedMeasurementFrequencies.everyFiveMinutes,
                        subject,
                        businessID,
                    });
                } catch (e) {
                    AuditService.publishEvent({
                        data: [e],
                        message: `Error adding schedule for dimension: ${dimensionId}`,
                        topic: AuditScope.ERROR,
                    });
                }
            }
        }

        await loadPoints(`${process.env.STAGE}-config`, process.env.INFLUX_ORG, [dimensionDBModel]);
        return { message: 'loaded dimension update', dimensionId: entity.dimensionId };
    }
    async removeAll(deleteDimensionDto): Promise<BasicResponseDTO> {
        const { businessID } = deleteDimensionDto;
        const dimensionIds = await this.InfluxService.getAllDimensionIds({ businessID });
        await Promise.all(
            dimensionIds.map(async ({ dimensionId }) => {
                await this.InfluxService.dropDimensionConfig(
                    `${process.env.STAGE}-config`,
                    process.env.INFLUX_ORG,
                    businessID,
                    dimensionId,
                );
            }),
        );

        return { message: 'deleted dimension document' };
    }

    async findByMeasurementId({ measurementId, businessID }) {
        const results = await this.InfluxService.getAllDimensionIdsWithMeasurementId({ businessID, measurementId });
        const dimensions = await Promise.all(
            results.map(async ({ dimensionId }) => {
                const {
                    data: [{ ...rest }],
                } = await this.findOne({ dimensionId, businessID });
                return rest;
            }),
        );
        const mostRecentElementInLedger = dimensions.filter(({ measurement }) => {
            if (measurement && measurement.measurementId === measurementId) {
                return true;
            } else {
                return false;
            }
        });

        return mostRecentElementInLedger.map(({ dimensionId }) => dimensionId);
    }
    public transformDtoToEntityInput(
        createDimensionDto: ReadDimensionResponseData | CreateDimensionDto,
        dimensionId,
    ): DimensionEntity {
        const {
            consumptionUnit,
            dimensionName,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            consumptionPrice,
            businessID,
            aggregationInterval: argumentAggregationInternal,
            aggregationMethod: argumentAggregationMethod,
            metadata,
        } = createDimensionDto;
        let measurementId;

        //eslint-disable-next-line
        //@ts-ignore
        if (createDimensionDto?.measurementId === null) {
            measurementId = undefined;
        }
        //eslint-disable-next-line
        //@ts-ignore
        else if (createDimensionDto?.measurement?.measurementId) {
            //eslint-disable-next-line
            //@ts-ignore
            measurementId = createDimensionDto?.measurement?.measurementId;
        } else {
            //eslint-disable-next-line
            //@ts-ignore
            measurementId = createDimensionDto?.measurementId;
        }
        const input = {
            typeofDimension: 'numerical',
            numerical: {
                numericalType: numericalType['int'],
                dimensionUnit: consumptionUnit.unit,
                dimensionUnitType: consumptionUnit.type.toLowerCase(),
                aggregationInterval: argumentAggregationInternal
                    ? argumentAggregationInternal
                    : aggregationInterval['Hour'],
                aggregationMethod: argumentAggregationMethod ? argumentAggregationMethod : aggregationMethod['max'],
                priceSegments: [
                    {
                        lowerLimit: '0',
                        upperLimit: 'inf',
                        price: consumptionPrice,
                    },
                ],
                sampleType: SampleType['gauge'],
                usageIncrement,
                rounding,
                usageEntitlement,
                overageAllowed,
            },
            businessID,
            dimensionId,
            dimensionName,
            categorical: {},
            measurementId,
            metadata,
        };
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        return input;
    }
    private determineAggregationScheduleInput(dimensionId, businessID: string): AggregationDto {
        return {
            dimensionId,
            businessID,
            rate: SupportedMeasurementFrequencies.daily,
            aggregationType: aggregationType.aggregation,
        };
    }
}

