    private calculateTotalAmountWithoutTax(): number {
        let totalAmount = 0;
        this.invoiceLineItems.getLineItems().forEach((lineItem) => {
            totalAmount += lineItem.quantity * lineItem.unitCost;
        });
        const total = parseFloat(totalAmount.toFixed(2));
        if (total < 0) {
            return 0.0;
        } else {
            return total;
        }
    }

