import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { overageAllowedEnum } from './create-dimension.dto.js';

/**
 * The value used on the `upperBound` field of a tier to indicate that the tier has no upper limit.
 */
export const INFINITE_UPPER_BOUND = 'inf';

/**
 * The maximum amount of decimal places supported on any price field.
 */
export const MAX_PRICE_DECIMAL_PLACES = 8;

/**
 * A loosely typed representation of a tier.
 * The tier fields are validated at runtime, therefore the values coming from the API cannot be trusted to be strings.
 */
export interface TierLike {
    tierPosition?: string;
    upperBound?: string;
    tierName?: string;
    unitPrice?: string;
}

/**
 * Determines if a given value can be safely treated as a numeric string.
 * Numeric values on dimensions are always represented as strings in order to avoid any loss of precision.
 */
export function isNumericString(value: unknown): boolean {
    if (typeof value !== 'string') {
        return false;
    }
    if (value.trim() === '') {
        return false;
    }
    const parsed = Number(value);
    return !isNaN(parsed) && isFinite(parsed);
}

/**
 * Determines if a dimension, or a dimension like input, is priced with volume based tiers.
 * An empty array, `null` and `undefined` all indicate that the dimension is not tiered.
 */
export function hasTiers(tiers: unknown): boolean {
    return Array.isArray(tiers) && tiers.length > 0;
}

/**
 * Returns a copy of the tiers sorted ascending by the numeric value of their `tierPosition`.
 * The original array is never mutated so the ordering supplied by the SaaS provider is preserved.
 */
export function sortTiers<T extends TierLike>(tiers: Array<T>): Array<T> {
    if (!Array.isArray(tiers)) {
        return [];
    }
    return [...tiers].sort((first, second) => Number(first?.tierPosition) - Number(second?.tierPosition));
}

/**
 * Returns the amount of decimal places of a numeric string.
 */
function decimalPlaces(value: string): number {
    return value.split('.')[1]?.length ?? 0;
}

function isEmptyValue(value: unknown): boolean {
    return value === undefined || value === null || value === '';
}

/**
 * Validates the tier collection of a dimension.
 *
 * The following rules are enforced:
 * - Tiered dimensions are mutually exclusive with `usageEntitlement`, `consumptionPrice` and `overageAllowed: true`
 * - `tierPosition` must be a unique numeric string
 * - `upperBound` must either be a positive numeric string or `"inf"`
 * - `"inf"` is only allowed on the last tier
 * - Upper bounds must strictly increase, therefore tiers can never overlap
 * - Upper bounds must be aligned with, meaning be a multiple of, the `usageIncrement` of the dimension
 * - Every tier after the first one must define a `unitPrice`, an omitted price on the first tier means a free tier
 *
 * @returns a list of human readable error messages, an empty list means the tiers are valid
 */
export function collectTierValidationErrors({
    tiers,
    usageIncrement,
    usageEntitlement,
    consumptionPrice,
    overageAllowed,
}: {
    tiers?: Array<TierLike> | null;
    usageIncrement?: string;
    usageEntitlement?: number | 'inf' | null;
    consumptionPrice?: string | null;
    overageAllowed?: overageAllowedEnum | null;
}): Array<string> {
    const errors: Array<string> = [];
    if (tiers === undefined || tiers === null) {
        return errors;
    }
    if (!Array.isArray(tiers)) {
        return ['tiers: must be an array of tier objects'];
    }
    if (tiers.length === 0) {
        // An empty collection of tiers is equivalent to a dimension without tiers
        return errors;
    }

    if (!isEmptyValue(usageEntitlement)) {
        errors.push('tiers: cannot be set on a dimension which has a usageEntitlement');
    }
    if (!isEmptyValue(consumptionPrice)) {
        errors.push('tiers: cannot be set on a dimension which has a consumptionPrice, price the tiers instead');
    }
    if (overageAllowed === overageAllowedEnum.true) {
        errors.push("tiers: cannot be set on a dimension which has overageAllowed set to 'true'");
    }

    tiers.forEach((tier, index) => {
        if (!tier || typeof tier !== 'object' || Array.isArray(tier)) {
            errors.push(`tiers: the tier at index ${index} must be an object`);
            return;
        }
        const { tierPosition, upperBound, tierName, unitPrice } = tier;
        if (!isNumericString(tierPosition)) {
            errors.push(`tiers: tierPosition: ${tierPosition} at index ${index} must be a numeric string`);
        }
        if (upperBound !== INFINITE_UPPER_BOUND) {
            if (!isNumericString(upperBound)) {
                errors.push(
                    `tiers: upperBound: ${upperBound} at index ${index} must either be a numeric string or "${INFINITE_UPPER_BOUND}"`,
                );
            } else if (Number(upperBound) <= 0) {
                errors.push(`tiers: upperBound: ${upperBound} at index ${index} must be greater than 0`);
            }
        }
        if (!isEmptyValue(tierName) && typeof tierName !== 'string') {
            errors.push(`tiers: tierName at index ${index} must be a string`);
        }
        if (!isEmptyValue(unitPrice)) {
            if (!isNumericString(unitPrice)) {
                errors.push(`tiers: unitPrice: ${unitPrice} at index ${index} must be a numeric string`);
            } else if (Number(unitPrice) < 0) {
                errors.push(`tiers: unitPrice: ${unitPrice} at index ${index} cannot be negative`);
            } else if (decimalPlaces(unitPrice) > MAX_PRICE_DECIMAL_PLACES) {
                errors.push(
                    `tiers: unitPrice: ${unitPrice} at index ${index} cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after the decimal place`,
                );
            }
        }
    });

    if (errors.length) {
        // The structure of the tiers is invalid, the collection as a whole cannot be validated any further
        return errors;
    }

    const positions = tiers.map(({ tierPosition }) => Number(tierPosition));
    if (new Set(positions).size !== positions.length) {
        errors.push('tiers: every tierPosition must be unique');
        return errors;
    }

    const sortedTiers = sortTiers(tiers);
    const increment = isNumericString(usageIncrement) ? Number(usageIncrement) : undefined;
    let previousUpperBound = 0;
    sortedTiers.forEach((tier, index) => {
        const { upperBound } = tier;
        if (upperBound === INFINITE_UPPER_BOUND) {
            if (index !== sortedTiers.length - 1) {
                errors.push(
                    `tiers: only the tier with the highest tierPosition can have an upperBound of "${INFINITE_UPPER_BOUND}"`,
                );
            }
            return;
        }
        const bound = Number(upperBound);
        if (bound <= previousUpperBound) {
            errors.push(
                `tiers: upperBound: ${upperBound} must be greater than the upperBound of the previous tier: ${previousUpperBound}, tiers cannot overlap`,
            );
        }
        if (increment !== undefined && increment > 0 && bound % increment !== 0) {
            errors.push(
                `tiers: upperBound: ${upperBound} must be a multiple of the usageIncrement: ${usageIncrement} of the dimension`,
            );
        }
        previousUpperBound = bound;
    });

    sortedTiers.forEach((tier, index) => {
        if (index === 0) {
            // An omitted unitPrice on the first tier represents a free tier
            return;
        }
        if (isEmptyValue(tier.unitPrice)) {
            errors.push(
                `tiers: unitPrice is required for every tier after the first one, it is missing on the tier with tierPosition: ${tier.tierPosition}`,
            );
        }
    });

    return errors;
}

/**
 * @author Paigo
 *
 * A class-validator constraint which validates the `tiers` field of a dimension.
 */
@ValidatorConstraint({ name: 'ValidateTiers', async: false })
@Injectable()
export class ValidateTiersRule implements ValidatorConstraintInterface {
    validate(tiers: Array<TierLike> | null, args: ValidationArguments) {
        return ValidateTiersRule.errorsForObject(tiers, args).length === 0;
    }

    defaultMessage(args: ValidationArguments) {
        const errors = ValidateTiersRule.errorsForObject(args?.value, args);
        if (errors.length) {
            return errors.join('; ');
        }
        return 'tiers: invalid tier configuration';
    }

    private static errorsForObject(tiers, args: ValidationArguments): Array<string> {
        const dimension = (args?.object ?? {}) as {
            usageIncrement?: string;
            usageEntitlement?: number | 'inf';
            consumptionPrice?: string;
            overageAllowed?: overageAllowedEnum;
        };
        return collectTierValidationErrors({
            tiers,
            usageIncrement: dimension?.usageIncrement,
            usageEntitlement: dimension?.usageEntitlement,
            consumptionPrice: dimension?.consumptionPrice,
            overageAllowed: dimension?.overageAllowed,
        });
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidateTiersRule,
        });
    };
}

