/**
 * @author Paigo
 *
 * @Class
 * A single volume based pricing tier of a dimension.
 * Tiers allow high volume usage to be billed with a different unit price than low volume usage.
 * All numerical values are represented as strings in order to avoid any loss of precision.
 */
export class DimensionTier {
    /**
     * The position of the tier relative to the other tiers of the dimension.
     * Tiers are always evaluated in ascending order of their position.
     * <br><br>
     * Example: `"1"`
     * @example "1"
     */
    @IsNumberString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'tierPosition',
        type: String,
        example: '1',
        required: true,
        description:
            'The position of the tier relative to the other tiers of the dimension. Tiers are evaluated in ascending order of their position.',
    })
    public tierPosition: string;

    /**
     * The inclusive upper bound of the tier in terms of usage.
     * The lower bound of a tier is the upper bound of the preceding tier, the first tier starts at zero.
     * Bounds must increase without overlapping and must be a multiple of the `usageIncrement` of the dimension.
     * The tier with the highest position may use `"inf"` to indicate that it has no upper limit.
     * <br><br>
     * Example: `"1000"`
     * @example "1000"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({
        name: 'upperBound',
        oneOf: [
            {
                type: 'string',
                description:
                    'The inclusive upper bound of the tier, must be a positive numeric string aligned with the usageIncrement of the dimension',
                example: '1000',
            },
            {
                type: 'string',
                format: 'inf',
                description: 'The tier has no upper limit, only allowed on the tier with the highest tierPosition',
                example: 'inf',
            },
        ],
        examples: ['1000', 'inf'],
        required: true,
    })
    public upperBound: string;

    /**
     * An optional friendly, human readable name of the tier.
     * When set the name is appended to the name of the line item generated for the tier.
     * <br><br>
     * Example: `"First 1000 API Calls"`
     * @example "First 1000 API Calls"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({
        name: 'tierName',
        type: String,
        example: 'First 1000 API Calls',
        required: false,
        description:
            'An optional friendly name of the tier, when set it is appended to the name of the line item generated for the tier.',
    })
    public tierName?: string;

    /**
     * The unit price of the usage which falls into this tier.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * The unit price is required on every tier except for the first one,
     * omitting the unit price on the first tier creates a free tier.
     * <br><br>
     * Example: `"0.05"`
     * @example "0.05"
     */
    @IsNumberString()
    @IsOptional()
    @ValidateDecimalPlace('unitPrice')
    @ApiProperty({
        name: 'unitPrice',
        type: String,
        example: '0.05',
        required: false,
        description:
            'The unit price of the usage which falls into this tier. Required on every tier except the first one, an omitted price on the first tier creates a free tier.',
    })
    public unitPrice?: string;

    constructor(tier?: DimensionTier) {
        if (tier) {
            const { tierPosition, upperBound, tierName, unitPrice } = tier;
            this.tierPosition = tierPosition;
            this.upperBound = upperBound;
            if (tierName !== undefined && tierName !== null) {
                this.tierName = tierName;
            }
            if (unitPrice !== undefined && unitPrice !== null) {
                this.unitPrice = unitPrice;
            }
        }
    }
}

