    public tiers?: DimensionTier[];

    constructor(numericalEntityInfo: Numerical) {
        if (numericalEntityInfo) {
            const {
                numericalType,
                dimensionUnit,
                aggregationInterval,
                aggregationMethod,
                priceSegments,
                sampleType,
                usageIncrement,
                rounding,
                usageEntitlement,
                overageAllowed,
