                tiers,
            } = numericalEntityInfo;
            this.numericalType = numericalType;
            this.dimensionUnit = dimensionUnit;
            this.sampleType = sampleType;
            this.aggregationInterval = aggregationInterval;
            this.aggregationMethod = aggregationMethod;
            this.priceSegments = priceSegments;
            this.usageIncrement = usageIncrement;
            this.rounding = rounding;
            this.usageEntitlement = usageEntitlement;
            this.overageAllowed = overageAllowed ? overageAllowed : overageAllowedEnum.false;
            this.dimensionUnitType = dimensionUnitType;
            if (tiers && tiers.length) {
                this.tiers = tiers.map((tier) => new DimensionTier(tier));
            }
        }
    }

    public static transformer = (
        {
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments,
            sampleType,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            dimensionUnitType,
            tiers,
        }: Numerical,
        point: Point,
    ): Point => {
        point.tag('numericalType', numericalType);
        point.tag('dimensionUnit', dimensionUnit);
        point.tag('aggregationInterval', aggregationInterval);
        point.tag('aggregationMethod', aggregationMethod);
        point.tag('sampleType', sampleType);
        point.tag('priceSegments', JSON.stringify(priceSegments));
        if (usageIncrement !== undefined) {
            point.tag('usageIncrement', usageIncrement.toString());
        }

        point.tag('rounding', rounding);
        if (usageEntitlement !== undefined && usageEntitlement !== null) {
            point.tag('usageEntitlement', usageEntitlement.toString());
        }

        if (overageAllowed !== undefined && overageAllowed !== null) {
            point.tag('overageAllowed', overageAllowed);
        }
        if (tiers && tiers.length) {
            point.tag('tiers', JSON.stringify(tiers));
        }

        point.tag('dimensionUnitType', dimensionUnitType);
        return point;
    };
    public static dbModelToEntity = (row: any): Numerical => {
        const {
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments,
            sampleType,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            dimensionUnitType,
            tiers,
        } = row;
        return new Numerical({
            numericalType,
            dimensionUnit,
            aggregationInterval,
            aggregationMethod,
            priceSegments: JSON.parse(priceSegments),
            sampleType,
            usageIncrement: parseInt(usageIncrement),
            rounding,
            usageEntitlement: usageEntitlement ? parseInt(usageEntitlement) : undefined,
            overageAllowed,
            dimensionUnitType,
            tiers: Numerical.parseTiers(tiers),
        });
    };

    /**
     * The tiers of a dimension are stored as a JSON string in the ledger.
     * Legacy dimensions, and dimensions without tiers, do not have the tag at all.
     */
    public static parseTiers(tiers: unknown): DimensionTier[] | undefined {
        if (tiers === undefined || tiers === null || tiers === '') {
            return undefined;
        }
        if (Array.isArray(tiers)) {
            return tiers.length ? tiers.map((tier) => new DimensionTier(tier)) : undefined;
        }
        if (typeof tiers !== 'string') {
            return undefined;
        }
        try {
            const parsed = JSON.parse(tiers);
            if (Array.isArray(parsed) && parsed.length) {
                return parsed.map((tier) => new DimensionTier(tier));
            }
            return undefined;
        } catch (e) {
            Numerical.logger.error(`Unable to parse the tiers of a dimension: ${tiers}`);
            return undefined;
        }
    }
}

