/**
 * Validates the volume based pricing tiers of a dimension which is being created.
 *
 * @throws BadRequestException when the tiers of the dimension are invalid
 */
public static validateTiers(dimension: {
    tiers?: unknown;
    usageIncrement?: string;
    usageEntitlement?: number | 'inf';
    consumptionPrice?: string;
    overageAllowed?: overageAllowedEnum;
}): void {
    const errors = collectTierValidationErrors({
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        tiers: dimension?.tiers,
        usageIncrement: dimension?.usageIncrement,
        usageEntitlement: dimension?.usageEntitlement,
        consumptionPrice: dimension?.consumptionPrice,
        overageAllowed: dimension?.overageAllowed,
    });
    if (errors.length) {
        throw new BadRequestException(errors.join('; '));
    }
}

/**
 * Validates the volume based pricing tiers of a dimension which is being updated.
 * When the update itself supplies the tiers, the tiers replace whatever pricing was configured before,
 * therefore the mutually exclusive fields are only evaluated against the fields of the update itself.
 * When the tiers are not part of the update, the already stored tiers are validated against the merged dimension.
 *
 * @throws BadRequestException when the resulting dimension would have an invalid tier configuration
 */
public static validateTiersForUpdate(storedDimension, updatedFields): void {
    const tiersAreUpdated = updatedFields && Object.prototype.hasOwnProperty.call(updatedFields, 'tiers');
    const tiers = tiersAreUpdated ? updatedFields?.tiers : storedDimension?.tiers;
    if (!hasTiers(tiers)) {
        // Removing the tiers, or a dimension without tiers, never requires any tier validation
        return;
    }
    const mutuallyExclusiveFieldSource = tiersAreUpdated ? updatedFields : { ...storedDimension, ...updatedFields };
    DimensionsService.validateTiers({
        tiers,
        usageIncrement:
            updatedFields?.usageIncrement !== undefined && updatedFields?.usageIncrement !== null
                ? updatedFields?.usageIncrement
                : storedDimension?.usageIncrement,
        usageEntitlement: mutuallyExclusiveFieldSource?.usageEntitlement,
        consumptionPrice: mutuallyExclusiveFieldSource?.consumptionPrice,
        overageAllowed: mutuallyExclusiveFieldSource?.overageAllowed,
    });
}

