/**
 * Determines if a dimension is priced with volume based tiers.
 */
public static isTieredDimension(dimension: ReadDimensionResponseData): boolean {
    return hasTiers(dimension?.tiers);
}

/**
 * Determines if a dimension has any pricing information attached to it.
 * Legacy dimensions can exist without any price, without tiers and without an entitlement,
 * those dimensions never contribute anything to an invoice.
 */
public static isPricedDimension(dimension: ReadDimensionResponseData): boolean {
    if (Billing.isTieredDimension(dimension)) {
        return true;
    }
    const { consumptionPrice } = dimension ?? ({} as ReadDimensionResponseData);
    if (consumptionPrice === undefined || consumptionPrice === null || `${consumptionPrice}`.trim() === '') {
        return false;
    }
    return !isNaN(parseFloat(consumptionPrice));
}

/**
 * Allocates the total usage of a dimension across its volume based pricing tiers.
 *
 * Tiers are evaluated in ascending order of their `tierPosition`.
 * The `upperBound` of every tier is inclusive, and the lower bound of a tier
 * is the upper bound of the tier which precedes it, the first tier starts at zero.
 *
 * @returns the usage which falls into every consumed tier, tiers without usage are omitted
 */
public static allocateUsageToTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number | string;
    tiers: Array<DimensionTier>;
}): Array<{ tier: DimensionTier; usage: number }> {
    const total = typeof totalUsage === 'string' ? parseFloat(totalUsage) : totalUsage;
    if (!hasTiers(tiers) || total === undefined || total === null || isNaN(total) || total <= 0) {
        return [];
    }
    const allocations: Array<{ tier: DimensionTier; usage: number }> = [];
    let allocatedUsage = 0;
    for (const tier of sortTiers(tiers)) {
        const remainingUsage = Billing.roundUsage(total - allocatedUsage);
        if (remainingUsage <= 0) {
            break;
        }
        const upperBound = tier?.upperBound === INFINITE_UPPER_BOUND ? Infinity : Number(tier?.upperBound);
        const capacityOfTier = Billing.roundUsage(upperBound - allocatedUsage);
        if (!(capacityOfTier > 0)) {
            // A tier which is fully contained in the usage of the preceding tiers cannot be consumed
            continue;
        }
        const usageForTier = Math.min(remainingUsage, capacityOfTier);
        allocations.push({ tier, usage: usageForTier });
        allocatedUsage = Billing.roundUsage(allocatedUsage + usageForTier);
    }
    return allocations;
}

/**
 * Guards the tier allocation against floating point drift while keeping the supported precision intact.
 */
private static roundUsage(usage: number): number {
    if (!isFinite(usage)) {
        return usage;
    }
    return parseFloat(usage.toFixed(8));
}

