/**
 * Converts the price of a dimension, or of one of its tiers, into the currency of the invoice.
 * The precision of the configured price is always preserved.
 */
static convertPriceToUnitCost({ price, exchangeRate }: { price?: string; exchangeRate: number }): number {
    const parsedPrice = parseFloat(price !== undefined && price !== null && price !== '' ? price : '0');
    const decimals = Offering.getDecimalsForNumber(parsedPrice);
    return Number((parsedPrice * exchangeRate).toFixed(decimals === 0 ? 2 : decimals));
}

/**
 * Creates one line item for every tier of a tiered dimension which has been consumed.
 * The usage of the dimension is allocated across the inclusive bounds of the tiers,
 * and every tier is priced with its own unit price.
 * When a tier has a `tierName` the name is appended to the name of the line item.
 */
static addTieredLineItemsForDimension({
    dimension,
    totalUsage,
    lineItems,
    exchangeRate,
    negative,
    offeringInstance,
}: {
    dimension: ReadDimensionResponseData;
    totalUsage: number | string;
    lineItems: InvoiceLineItems;
    exchangeRate: number;
    negative?: boolean;
    offeringInstance: Offering;
}): InvoiceLineItems {
    const {
        dimensionId,
        dimensionName,
        usageIncrement,
        tiers,
        consumptionUnit: { unit, type },
    } = dimension;
    const allocations = Billing.allocateUsageToTiers({ totalUsage, tiers });
    allocations.forEach(({ tier, usage }) => {
        const unitCost = Offering.convertPriceToUnitCost({ price: tier?.unitPrice, exchangeRate });
        if (unitCost === 0 && offeringInstance?.settings?.freeDimensionOnInvoice === FreeDimensionOnInvoice.hide) {
            // Free tiers are hidden when the SaaS provider asked for free dimensions to be hidden
            return;
