            total: usage,
            dimensionType: type,
            dimensionId,
            dimensionName,
            offeringName: offeringInstance.offeringName,
            usageIncrement: parseInt(usageIncrement),
            dimensionUnit: unit,
            negative,
        });
        const nameWithTier = tier?.tierName ? `${displayName} - ${tier.tierName}` : displayName;
        lineItems.addLineItem(new InvoiceLineItem(nameWithTier, displayTotal, unitCost));
    });
    return lineItems;
}

