import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
    CreateDimensionDto,
    DimensionTier,
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../dimensions/dto/create-dimension.dto.js';
import { Billing } from '../billing/entities/billing.entity.js';
import { DimensionEntity, Numerical } from '../dimensions/entities/dimensions.entity.js';
import { DimensionsService } from '../dimensions/dimensions.service.js';
import { InvoiceLineItem, InvoiceLineItems } from '../invoice/entities/invoice.entity.js';
import { Offering, UsageBased } from '../offering/entities/offeringPackage.entity.js';
import { ReadDimensionResponseData } from '../dimensions/dto/read-dimension.dto.js';
import { OfferingType } from '../offering/entities/OfferingType.js';
import { SupportedCurrencies } from '../offering/dto/SupportedCurrencies.js';
import { ValidBillingCycles } from '../offering/dto/createOffering.dto.js';
import { ReadSettingsResponseData } from '../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../setting/dto/FreeDimensionOnInvoice.js';
import { CustomerService } from '../customer/customer.service.js';
import { InvoicesService } from '../invoice/invoices.service.js';
import { ReadCustomerUsageData } from '../customer/dto/read-customer.dto.js';

jest.mock('../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const baseDimension = {
    dimensionName: 'API Call',
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
};

const tiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'Starter', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: '2000', tierName: 'Growth', unitPrice: '0.03' },
    { tierPosition: '3', upperBound: 'inf', tierName: 'Volume', unitPrice: '0.01' },
];

const validateDto = async (input) => validate(plainToInstance(CreateDimensionDto, input));

describe('tier scratch', () => {
    test('valid tiered dimension passes validation', async () => {
        const errors = await validateDto({ ...baseDimension, tiers });
        expect(errors).toEqual([]);
    });
    test('tiers with consumptionPrice fail', async () => {
        const errors = await validateDto({ ...baseDimension, tiers, consumptionPrice: '1.00' });
        expect(errors.length).toBeGreaterThan(0);
        console.log(JSON.stringify(errors.map((e) => e.constraints)));
    });
    test('tiers with entitlement fail', async () => {
        const errors = await validateDto({ ...baseDimension, tiers, usageEntitlement: 100 });
        expect(errors.length).toBeGreaterThan(0);
    });
    test('tiers with overage true fail', async () => {
        const errors = await validateDto({ ...baseDimension, tiers, overageAllowed: overageAllowedEnum.true });
        expect(errors.length).toBeGreaterThan(0);
    });
    test('descending bounds fail', async () => {
        const errors = await validateDto({
            ...baseDimension,
            tiers: [
                { tierPosition: '1', upperBound: '2000', unitPrice: '0.05' },
                { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
            ],
        });
        expect(errors.length).toBe(1);
        console.log(JSON.stringify(errors[0].constraints));
    });
    test('misaligned bounds fail', async () => {
        const errors = await validateDto({
            ...baseDimension,
            usageIncrement: '10',
            tiers: [{ tierPosition: '1', upperBound: '1005', unitPrice: '0.05' }],
        });
        expect(errors.length).toBe(1);
    });
    test('inf not at the end fails', async () => {
        const errors = await validateDto({
            ...baseDimension,
            tiers: [
                { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
            ],
        });
        expect(errors.length).toBe(1);
    });
    test('missing unitPrice after first tier fails, first tier may be free', async () => {
        expect(
            await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
            }),
        ).toHaveLength(1);
        expect(
            await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
            }),
        ).toEqual([]);
    });

    test('allocation splits usage across inclusive bounds', () => {
        expect(Billing.allocateUsageToTiers({ totalUsage: 2500, tiers: tiers as DimensionTier[] })).toEqual([
            { tier: tiers[0], usage: 1000 },
            { tier: tiers[1], usage: 1000 },
            { tier: tiers[2], usage: 500 },
        ]);
        expect(Billing.allocateUsageToTiers({ totalUsage: 1000, tiers: tiers as DimensionTier[] })).toEqual([
            { tier: tiers[0], usage: 1000 },
        ]);
        expect(Billing.allocateUsageToTiers({ totalUsage: 0, tiers: tiers as DimensionTier[] })).toEqual([]);
        // unsorted input
        expect(
            Billing.allocateUsageToTiers({ totalUsage: 1500, tiers: [tiers[2], tiers[1], tiers[0]] as DimensionTier[] }),
        ).toEqual([
            { tier: tiers[0], usage: 1000 },
            { tier: tiers[1], usage: 500 },
        ]);
    });

    test('entity round trip persists tiers', () => {
        const service = new DimensionsService(null, null, null, null);
        const input = service.transformDtoToEntityInput({ ...baseDimension, tiers, businessID: 'biz' } as any, 'dim1');
        expect(input.numerical.tiers).toEqual(tiers);
        const point = DimensionEntity.transformer(new DimensionEntity(input), {
            getPoint: (measurement) => {
                const tags = {};
                const point = {
                    tag: (k, v) => {
                        tags[k] = v;
                        return point;
                    },
                    stringField: () => point,
                    tags,
                };
                return point;
            },
        } as any);
        // eslint-disable-next-line
        // @ts-ignore
        const tags = point.tags;
        expect(JSON.parse(tags.tiers)).toEqual(tiers);
        const numerical = Numerical.dbModelToEntity(tags);
        expect(numerical.tiers).toEqual(tiers);
        const dto = new CreateDimensionDto(
            new DimensionEntity({ ...input, numerical, typeofDimension: 'numerical' } as any),
        );
        expect(dto.tiers).toEqual(tiers);
        expect(dto.consumptionPrice).toBeUndefined();
    });

    test('update validation', () => {
        expect(() =>
            DimensionsService.validateTiersForUpdate({ ...baseDimension, consumptionPrice: '1.00' }, { tiers }),
        ).not.toThrow();
        expect(() =>
            DimensionsService.validateTiersForUpdate({ ...baseDimension, tiers }, { consumptionPrice: '1.00' }),
        ).toThrow();
        expect(() => DimensionsService.validateTiersForUpdate({ ...baseDimension, tiers }, { tiers: null })).not.toThrow();
        expect(() =>
            DimensionsService.validateTiersForUpdate(
                { ...baseDimension, usageIncrement: '10' },
                { tiers: [{ tierPosition: '1', upperBound: '1005', unitPrice: '1' }] },
            ),
        ).toThrow();
    });

    describe('billing line items', () => {
        let customerService: CustomerService;
        let invoicesService: InvoicesService;
        const settings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
        const usageOffering = {
            offeringId: '123',
            offeringName: 'My Offering',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            dimensions: [],
            billingCycle: ValidBillingCycles.monthly,
        };
        const mockUsage = (value: string) => {
            jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
                async () =>
                    ({
                        message: 'fake',
                        data: [{ dimensionId: 'dim1', usage: [{ value }] }],
                    }) as ReadCustomerUsageData,
            );
        };
        beforeEach(() => {
            //eslint-disable-next-line
            //@ts-ignore
            customerService = new CustomerService();
            //eslint-disable-next-line
            //@ts-ignore
            invoicesService = new InvoicesService();
        });
        const run = async (dimension: ReadDimensionResponseData, currency = SupportedCurrencies.USD) => {
            const offeringInstance = Offering.getInstance(
                { ...usageOffering, dimensions: [dimension], currency },
                'cust',
                'biz',
                invoicesService,
                settings,
            );
            return (
                await Offering.getLineItemsForUsage({
                    startDate: new Date('2023-08-01'),
                    endDate: new Date('2023-08-31'),
                    lineItems: new InvoiceLineItems(),
                    businessID: 'biz',
                    customerId: 'cust',
                    customerService,
                    dimensions: [dimension],
                    offeringInstance,
                    customer: { currency } as any,
                })
            ).getLineItems();
        };

        test('one line item per consumed tier', async () => {
            mockUsage('2500');
            const items = await run({ ...baseDimension, dimensionId: 'dim1', tiers } as any);
            expect(items).toEqual([
                expect.objectContaining(new InvoiceLineItem('API Call - My Offering - Starter', 1000, 0.05)),
                expect.objectContaining(new InvoiceLineItem('API Call - My Offering - Growth', 1000, 0.03)),
                expect.objectContaining(new InvoiceLineItem('API Call - My Offering - Volume', 500, 0.01)),
            ]);
        });
        test('usage increment divides quantities', async () => {
            mockUsage('2500');
            const items = await run({
                ...baseDimension,
                usageIncrement: '10',
                dimensionId: 'dim1',
                tiers,
            } as any);
            expect(items.map((i) => [i.name, i.quantity, i.unitCost])).toEqual([
                ['API Call - My Offering - Starter', 100, 0.05],
                ['API Call - My Offering - Growth', 100, 0.03],
                ['API Call - My Offering - Volume', 50, 0.01],
            ]);
        });
        test('precision and currency conversion', async () => {
            mockUsage('1500');
            const items = await run(
                {
                    ...baseDimension,
                    dimensionId: 'dim1',
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '1.00' },
                    ],
                } as any,
                SupportedCurrencies.EUR,
            );
            expect(items.map((i) => [i.name, i.quantity, i.unitCost])).toEqual([
                ['API Call - My Offering', 1000, 1.12345678],
                ['API Call - My Offering', 500, 0.91],
            ]);
        });
        test('free first tier', async () => {
            mockUsage('1500');
            const items = await run({
                ...baseDimension,
                dimensionId: 'dim1',
                tiers: [
                    { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.10' },
                ],
            } as any);
            expect(items.map((i) => [i.name, i.quantity, i.unitCost])).toEqual([
                ['API Call - My Offering - Free', 1000, 0],
                ['API Call - My Offering', 500, 0.1],
            ]);
        });
        test('unpriced legacy dimension produces no line items', async () => {
            mockUsage('1500');
            const items = await run({ ...baseDimension, dimensionId: 'dim1' } as any);
            expect(items).toEqual([]);
        });
        test('non tiered dimension unchanged', async () => {
            mockUsage('1500');
            const items = await run({ ...baseDimension, dimensionId: 'dim1', consumptionPrice: '0.25' } as any);
            expect(items.map((i) => [i.name, i.quantity, i.unitCost])).toEqual([['API Call - My Offering', 1500, 0.25]]);
        });
    });
});

