import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import {
    CreateDimensionDto,
    DimensionTier,
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from './dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from './dto/read-dimension.dto.js';
import { DimensionsService } from './dimensions.service.js';
import { DimensionEntity, Numerical } from './entities/dimensions.entity.js';
import { Billing } from '../billing/entities/billing.entity.js';
import { InvoiceLineItems } from '../invoice/entities/invoice.entity.js';
import { InvoicesService } from '../invoice/invoices.service.js';
import { CustomerService } from '../customer/customer.service.js';
import { ReadCustomerUsageData } from '../customer/dto/read-customer.dto.js';
import { Offering } from '../offering/entities/offeringPackage.entity.js';
import { OfferingType } from '../offering/entities/OfferingType.js';
import { SupportedCurrencies } from '../offering/dto/SupportedCurrencies.js';
import { ValidBillingCycles } from '../offering/dto/createOffering.dto.js';
import { ReadSettingsResponseData } from '../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../setting/dto/FreeDimensionOnInvoice.js';

jest.mock('../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const baseDimension = {
    dimensionName: 'API Call',
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
};

const tiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'Starter', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: '2000', tierName: 'Growth', unitPrice: '0.03' },
    { tierPosition: '3', upperBound: 'inf', tierName: 'Volume', unitPrice: '0.01' },
];

const validateDimension = async (input) => validate(plainToInstance(CreateDimensionDto, input));

describe('Dimension pricing tiers', () => {
    describe('validation', () => {
        test('a tiered dimension without any other pricing field is valid', async () => {
            expect(await validateDimension({ ...baseDimension, tiers })).toEqual([]);
        });
        test('tiers are mutually exclusive with consumptionPrice', async () => {
            const errors = await validateDimension({ ...baseDimension, tiers, consumptionPrice: '1.00' });
            expect(errors.length).toBeGreaterThan(0);
        });
        test('tiers are mutually exclusive with usageEntitlement', async () => {
            const errors = await validateDimension({ ...baseDimension, tiers, usageEntitlement: 100 });
            expect(errors.length).toBeGreaterThan(0);
        });
        test('tiers are mutually exclusive with overageAllowed set to true', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers,
                overageAllowed: overageAllowedEnum.true,
            });
            expect(errors.length).toBeGreaterThan(0);
        });
        test('upper bounds must increase without overlapping', async () => {
            const errors = await validateDimension({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '2000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
                ],
            });
            expect(errors).toHaveLength(1);
        });
        test('upper bounds must be aligned with the usage increment', async () => {
            expect(
                await validateDimension({
                    ...baseDimension,
                    usageIncrement: '10',
                    tiers: [{ tierPosition: '1', upperBound: '1005', unitPrice: '0.05' }],
                }),
            ).toHaveLength(1);
            expect(
                await validateDimension({
                    ...baseDimension,
                    usageIncrement: '10',
                    tiers: [{ tierPosition: '1', upperBound: '1000', unitPrice: '0.05' }],
                }),
            ).toEqual([]);
        });
        test('an infinite upper bound is only allowed on the last tier', async () => {
            expect(
                await validateDimension({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                        { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
                    ],
                }),
            ).toHaveLength(1);
        });
        test('only the first tier can omit the unit price', async () => {
            expect(
                await validateDimension({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: 'inf' },
                    ],
                }),
            ).toHaveLength(1);
            expect(
                await validateDimension({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                }),
            ).toEqual([]);
        });
        test('every tier position must be a unique numeric string', async () => {
            expect(
                await validateDimension({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                        { tierPosition: '1', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                }),
            ).toHaveLength(1);
            expect(
                await validateDimension({
                    ...baseDimension,
                    tiers: [{ tierPosition: 'first', upperBound: '1000', unitPrice: '0.05' }],
                }),
            ).toHaveLength(1);
        });
        test('a dimension without tiers is validated exactly like before', async () => {
            expect(await validateDimension({ ...baseDimension, consumptionPrice: '0.05' })).toEqual([]);
            expect(await validateDimension({ ...baseDimension, usageEntitlement: 1000 })).toEqual([]);
        });
    });

    describe('persistence', () => {
        const dimensionsService = new DimensionsService(undefined, undefined, undefined, undefined);
        const collectTags = (entity: DimensionEntity): Record<string, string> => {
            const tags: Record<string, string> = {};
            const point = {
                tag: (key: string, value: string) => {
                    tags[key] = value;
                    return point;
                },
                stringField: () => point,
            };
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            //@ts-ignore
            DimensionEntity.transformer(entity, { getPoint: () => point });
            return tags;
        };

        test('the tiers of a dimension survive a full round trip through the ledger', () => {
            const input = dimensionsService.transformDtoToEntityInput(
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
                { ...baseDimension, tiers, businessID: 'fakeBusinessID' },
                'fakeDimensionId',
            );
            expect(input.numerical.tiers).toEqual(tiers);
            const tags = collectTags(new DimensionEntity(input));
            expect(JSON.parse(tags.tiers)).toEqual(tiers);

            const numerical = Numerical.dbModelToEntity(tags);
            expect(numerical.tiers).toEqual(tiers);

            const readDimension = new CreateDimensionDto(
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
                new DimensionEntity({ ...input, numerical }),
            );
            expect(readDimension.tiers).toEqual(tiers);
            expect(readDimension.consumptionPrice).toBeUndefined();
        });
        test('a dimension without tiers is persisted without the tiers tag', () => {
